class Solution {
    public long goodTriplets(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int[] pos2 = new int[n];
        for (int i = 0; i < n; i++) pos2[nums2[i]] = i;
        int[] bit = new int[n + 1];
        long ans = 0;
        for (int j = 0; j < n; j++) {
            int y = pos2[nums1[j]];
            long leftSmaller = query(bit, y - 1);
            long rightGreater = (n - 1 - y) - (j - leftSmaller);
            ans += leftSmaller * rightGreater;
            add(bit, y, 1, n);
        }
        return ans;
    }
    private void add(int[] bit, int idx, int val, int n) {
        for (++idx; idx <= n; idx += idx & -idx) bit[idx] += val;
    }
    private int query(int[] bit, int idx) {
        int s = 0;
        for (++idx; idx > 0; idx -= idx & -idx) s += bit[idx];
        return s;
    }
}

